-- 1:1 — User has one Profile
CREATE TABLE "user" (
    user_id BIGSERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL
);

CREATE TABLE profile (
    profile_id BIGSERIAL PRIMARY KEY,
    bio TEXT,
    user_id BIGINT UNIQUE NOT NULL,  -- FK on dependent side, UNIQUE enforces 1:1
    CONSTRAINT fk_user FOREIGN KEY (user_id) REFERENCES "user"(user_id)
);

-- 1:N — Department has many Employees
CREATE TABLE department (
    dept_id BIGSERIAL PRIMARY KEY,
    dept_name VARCHAR(100) NOT NULL
);

CREATE TABLE employee (
    emp_id BIGSERIAL PRIMARY KEY,
    emp_name VARCHAR(100),
    dept_id BIGINT NOT NULL,         -- FK on the N side (many employees)
    CONSTRAINT fk_dept FOREIGN KEY (dept_id) REFERENCES department(dept_id)
);

-- M:N — Students enroll in Courses
CREATE TABLE student (student_id BIGSERIAL PRIMARY KEY, name VARCHAR(100));
CREATE TABLE course (course_id BIGSERIAL PRIMARY KEY, title VARCHAR(100));

CREATE TABLE enrollment (            -- Junction table for M:N
    student_id BIGINT,
    course_id BIGINT,
    enrolled_date DATE DEFAULT CURRENT_DATE,
    PRIMARY KEY (student_id, course_id),
    CONSTRAINT fk_student FOREIGN KEY (student_id) REFERENCES student(student_id),
    CONSTRAINT fk_course FOREIGN KEY (course_id) REFERENCES course(course_id)
);
